toolCalls.args:
{"command":"$lines = Get-Content .\input\session.jsonl
for ($i=0; $i -lt $lines.Count; $i++) {
  $line = $lines[$i]
  try { $o = $line | ConvertFrom-Json } catch { Write-Output ("{0}: UNPARSEABLE" -f $i); continue }
  $t = $o.timestamp
  $type = $o.type
  $desc = ""
  if ($o.payload) {
    $p = $o.payload
    if ($p.type) { $desc += "payload.type=" + $p.type }
    if ($p.name) { $desc += " name=" + $p.name }
    if ($p.info -and $p.info.total_token_usage) { $desc += " tokens=" + $p.info.total_token_usage.total_tokens }
    if ($p.usage -and $p.usage.usage) { $desc += " usage=" + $p.usage.usage.total_tokens }
  }
  Write-Output ("{0} [{1}] {2} :: {3}" -f $i, $type, $t, $desc)
}"}

{"command":"$lines = Get-Content .\input\session.jsonl
for ($i=0; $i -lt $lines.Count; $i++) {
  $line = $lines[$i]
  if ($line.Length -gt 600000) { Write-Output ("{0}: SKIPPED len={1}" -f $i, $line.Length); continue }
  try { $o = $line | ConvertFrom-Json } catch { continue }
  if ($o.type -eq 'response_item' -and $o.payload.type -eq 'message') {
    $role = $o.payload.role
    $texts = @()
    foreach ($c in $o.payload.content) {
      if ($c.type -eq 'input_text' -or $c.type -eq 'output_text') { $texts += $c.text }
      elseif ($c.text) { $texts += $c.text }
    }
    $joined = ($texts -join "`n")
    if ($joined.Length -gt 3000) { $joined = $joined.Substring(0,3000) + " ...[TRUNC len=" + (($texts -join "`n").Length) + "]" }
    Write-Output ("--- line {0} role={1} ---" -f $i, $role)
    Write-Output $joined
    Write-Output ""
  }
}"}

{"command":"cd .
