{"command":"$lines = Get-Content .\input\session.jsonl
for ($i=0; $i -lt $lines.Count; $i++) {
  $line = $lines[$i]
  try { $o = $line | ConvertFrom-Json } catch { continue }
  if ($o.type -eq 'response_item' -and $o.payload.type -eq 'custom_tool_call') {
    $in = $o.payload.input
    $short = $in
    if ($short.Length -gt 700) { $short = $short.Substring(0,700) + " ...[+" + ($in.Length-700) + " chars]" }
    Write-Output ("### line {0} call_id={1} status={2}" -f $i, $o.payload.call_id, $o.payload.status)
    Write-Output $short
    Write-Output ""
  }
}"}

