{"command":"$lines = Get-Content .\input\session.jsonl
function Get-OutputText($idx) {
  $line = $lines[$idx]
  try { $o = $line | ConvertFrom-Json } catch { return @() }
  if ($o.type -ne 'response_item') { return @() }
  $p = $o.payload
  if ($p.type -ne 'custom_tool_call_output') { return @() }
  $parts = @()
  foreach ($it in $p.output) { if ($it.text) { $parts += $it.text } }
  return $parts
}
Write-Output "######## OUTPUT for line 21 call (git status at start) - line 24 ########"
