$txt = $txt -replace "`r", ""
$txtLines = $txt -split "`n"
$txtLines | Select-String -Pattern '^(\?\?|[ MADRCU]{1,2})\s' | Select-Object -First 60 | ForEach-Object { $_.Line }"}

